using System.IO.Compression;using System.Security.Cryptography.X509Certificates;using System.Text;using CertificateManager.Application;using CertificateManager.Domain;
namespace CertificateManager.UnitTests;
public class CertificateServicesTests {
 [Fact] public void GeneratesExpectedCertificateAndExports(){var service=new CertificateGenerator();var r=new GenerateCertificateRequest(Guid.NewGuid(),"api-prod","api.example",365,"owner@example.com");var result=service.Generate(r,"user","Contoso","Production","API",null);using var cert=new X509Certificate2(result.Pfx,result.Password,X509KeyStorageFlags.EphemeralKeySet);Assert.Equal(3072,cert.GetRSAPublicKey()!.KeySize);Assert.Equal("CN=api.example",cert.Subject);Assert.True(cert.HasPrivateKey);Assert.NotEmpty(result.Cer);Assert.Equal(cert.Thumbprint,result.Metadata.Thumbprint);Assert.InRange((result.Metadata.ValidUntil-result.Metadata.ValidFrom).TotalDays,364.9,365.1);using var zip=new ZipArchive(new MemoryStream(result.Package));Assert.Equal(4,zip.Entries.Count);Assert.DoesNotContain(zip.Entries,e=>e.FullName.Contains("password",StringComparison.OrdinalIgnoreCase));}
 [Fact] public void CalendarIsStandardsShapedAndHasAlarms(){var c=new CertificateRecord{ServiceId=Guid.NewGuid(),Name="api",Subject="CN=api",Issuer="CN=api",Thumbprint="ABC",SerialNumber="1",CreatedByUserId="u",PrimaryOwnerEmail="a@b.test",ValidUntil=DateTimeOffset.UtcNow.AddDays(365),RenewalDueAt=DateTimeOffset.UtcNow.AddDays(335)};var text=Encoding.UTF8.GetString(CalendarGenerator.Generate(c,"Contoso","Prod","API"));Assert.StartsWith("BEGIN:VCALENDAR\r\n",text);Assert.Contains("VERSION:2.0",text);Assert.Equal(2,text.Split("BEGIN:VALARM").Length-1);Assert.EndsWith("END:VCALENDAR\r\n",text);}
 [Theory][InlineData(-1,"Expired")][InlineData(3,"Critical")][InlineData(20,"RenewalRequired")][InlineData(45,"RenewalUpcoming")][InlineData(100,"Healthy")]public void CalculatesHealth(int days,string expected)=>Assert.Equal(expected,CertificateHealth.Calculate(DateTimeOffset.UtcNow.AddDays(days),DateTimeOffset.UtcNow));
 [Fact] public void PasswordsAreStrongAndUnique(){var a=PasswordGenerator.Generate();var b=PasswordGenerator.Generate();Assert.Equal(24,a.Length);Assert.NotEqual(a,b);Assert.All(new[]{a,b},x=>Assert.Contains(x,c=>!char.IsLetterOrDigit(c)));}
}
